#include <iostream>
#include <bitset>

#define C 300000

using namespace std;

int main() {
    int n, q;
    int c[300000], query[100000];
    bitset<C+1> has_c; // Use bitset instead of bool array

    cin >> n >> q;
    for (int i = 0; i < n; i++) {
        cin >> c[i];
        has_c[c[i]] = true; // Set bits for existing values
    }

    for (int i = 0; i < q; i++) {
        cin >> query[i];
        int max_r = -1;
        for (int r = query[i] - 1; r >= 0; r--) {
            // Check multiples of query[i] only once
            for (int k = 0; k * query[i] <= C; k++) {
                int x = k * query[i] + r;
                if (x > C) {
                    break;
                }
                if (has_c[x]) {
                    max_r = max(r, max_r);
                    break; // Break out of the inner loop as we found a valid x
                }
            }
            if (max_r >= 0) {
                break; // Break out of the outer loop if we found a valid max_r
            }
        }
        cout << max_r << endl;
    }

    return 0;
}

