    for (int i = 0; i < q; i++) {
        cin >> query[i];
    }

    for (int i = 0; i < q; i++) {
        int max_r = -1;
        int query_val = query[i];
        for (int r = query_val - 1; r >= 0; r--) {
            int k = 0;
            int x;
            while (true) {
                x = k * query_val + r;
                if (x > C) {
                    break;
                }
                if (has_c[x]) {
                    max_r = r; // Update max_r directly
                    break;
